// Exact public layout only; no private surrounding conversation.
export const mixerSample =
  '{@body const [instrumental,setInstrumental] = DIL.useState(90)}\n{@body const [voice1,setVoice1] = DIL.useState(35)}\n{@body const [voice2,setVoice2] = DIL.useState(75)}\n{@body const [microphone,setMicrophone] = DIL.useState(65)}\n{@body const channels = [{name:"Минусовка",value:instrumental,set:setInstrumental,icon:"music"},{name:"Исполнитель 1",value:voice1,set:setVoice1,icon:"mic-vocal"},{name:"Исполнитель 2",value:voice2,set:setVoice2,icon:"mic-vocal"},{name:"Твой микрофон",value:microphone,set:setMicrophone,icon:"mic"}]}\n<box border radius="xl" padding={3} gap={3}>\n  <row align="center" justify="between">\n    <box gap={1}>\n      **Karaoke — Audio Mixer**\n      <text color="secondary" size="xs">Пример интерактивного микшера</text>\n    </box>\n    <button size="sm" color="secondary" variant="outline" onClick={()=>{setInstrumental(100);setVoice1(0);setVoice2(0);setMicrophone(65)}}>Сброс</button>\n  </row>\n  {#each channels as ch}\n    <box gap={1} key={ch.name}>\n      <row align="center" justify="between">\n        <row align="center" gap={2}>\n          <icon name={ch.icon} color="secondary"/>\n          <text weight="medium" size="sm">{ch.name}</text>\n        </row>\n        <text tabularNums color="secondary" size="xs">{ch.value}%</text>\n      </row>\n      <row gap={3} align="center">\n        <box flex="1">\n          <slider min={0} max={100} step={5} value={ch.value} onChange={ch.set}/>\n        </box>\n        <button size="sm" uniform color="secondary" variant="outline" onClick={()=>ch.set(ch.value===0?100:0)}>\n          <icon name={ch.value===0?"volume-x":"volume-2"}/>\n        </button>\n      </row>\n    </box>\n  {/each}\n  <divider color="subtle"/>\n  <row gap={2} wrap="wrap">\n    <button size="sm" color="secondary" variant="outline" onClick={()=>{setInstrumental(100);setVoice1(0);setVoice2(0)}}>Чистое караоке</button>\n    <button size="sm" color="secondary" variant="outline" onClick={()=>{setInstrumental(100);setVoice1(40);setVoice2(40)}}>Подпевание</button>\n    <button size="sm" color="secondary" variant="outline" onClick={()=>{setInstrumental(100);setVoice1(0);setVoice2(100)}}>Дуэт с оригиналом</button>\n  </row>\n</box>\n';
